<?php
namespace App\Http\Controllers;
use App\Models\{Product,Supplier,Salesperson,StockTransaction};
class DashboardController extends Controller { public function __invoke(){ $months=collect(range(11,0))->map(fn($n)=>now()->subMonths($n)); $series=fn($type)=>$months->map(fn($m)=>StockTransaction::where('type',$type)->whereYear('transaction_date',$m->year)->whereMonth('transaction_date',$m->month)->withCount('items')->get()->sum('items_count'))->values(); return view('dashboard',['in'=>StockTransaction::where('type','in')->whereDate('transaction_date',today())->count(),'out'=>StockTransaction::where('type','out')->whereDate('transaction_date',today())->count(),'months'=>$months,'inSeries'=>$series('in'),'outSeries'=>$series('out'),'products'=>Product::count(),'suppliers'=>Supplier::count(),'sales'=>Salesperson::count(),'value'=>Product::selectRaw('sum(current_stock * cost_price) as total')->value('total'),'low'=>Product::whereColumn('current_stock','<=','minimum_stock')->orderBy('current_stock')->take(6)->get(),'recent'=>StockTransaction::with('user')->latest()->take(7)->get(),'top'=>Product::orderByDesc('current_stock')->take(5)->get()]);}}
